public List<Map<String, Object>> getWithFingerprint(String cacheName, String key,
                                                    CaffeineCache l1, RedisTemplate<String, Object> l2,
                                                    Supplier<List<Map<String, Object>>> loader) {
    String fpKey = "uqt:" + cacheName + ":fp:" + key;
    String currentFp = loadFingerprint(key);          // MAX(update_time)，带同样的过滤条件
    Object cached = l1.getIfPresent(key);
    if (cached != null && currentFp.equals(l1.getIfPresent(fpKey))) {
        return cast(cached);
    }
    Object fromRedis = l2.opsForValue().get(dataKey(cacheName, key));
    Object redisFp = l2.opsForValue().get(fpKey);
    if (fromRedis != null && currentFp.equals(redisFp)) {
        l1.put(key, fromRedis);
        l1.put(fpKey, currentFp);
        return cast(fromRedis);
    }
    List<Map<String, Object>> fresh = loader.get();
    l1.put(key, fresh);
    l1.put(fpKey, currentFp);
    l2.opsForValue().set(dataKey(cacheName, key), fresh, DATA_TTL_180S);
    l2.opsForValue().set(fpKey, currentFp, FP_TTL_30S);
    return fresh;
}

private Object getSafe(String cacheName, String key, CaffeineCache l1,
                       RedisTemplate<String, Object> l2) {
    Object local = l1.getIfPresent(key);
    if (local != null) {
        return local;
    }
    try {
        return l2.opsForValue().get(dataKey(cacheName, key));
    } catch (Exception e) {
        // Redis 故障：只打 warn 并降级直查数据库，不把缓存故障升级成查询故障
        log.warn("redis get failed, degrade to db. cacheName: {}, key: {}", cacheName, e);
        return null;
    }
}
